import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { loginUser } from "../services/api"; // Ensure this function is correctly implemented in your API service
import { Box, TextField, Button, Typography } from "@mui/material";

const Login = () => {
    const [username, setUsername] = useState("");
    const [password, setPassword] = useState("");
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const { data } = await loginUser({ username, password });
            console.log(data);  // Log the response to see what the backend is returning
            if (data.token) {
                localStorage.setItem("token", data.token);
                if (data.user.role === "superadmin") navigate("/superadmin");
                else if (data.user.role === "admin") navigate("/admin");
                else navigate("/user");
            } else {
                alert("Invalid Credentials");
            }
        } catch (error) {
            console.error("Login failed:", error);
            alert("Invalid Credentials");
        }
    };
    

    return (
        <Box padding={4}>
            <Typography variant="h5" gutterBottom>
                Login
            </Typography>
            <form onSubmit={handleSubmit}>
                <TextField
                    label="Username"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    fullWidth
                    margin="normal"
                />
                <TextField
                    label="Password"
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    fullWidth
                    margin="normal"
                />
                <Button type="submit" variant="contained" color="primary">
                    Login
                </Button>
            </form>
        </Box>
    );
};

export default Login;
